    BOOK_CACHE = None

    def next_move(self, board: Board) -> Move:
        start_time = time.perf_counter()
        self._eval_count = 0
        type(self).SEARCH_HASH_GET_COUNT = 0
        type(self).SEARCH_HASH_REG_COUNT = 0
        move_no = self._move_number(board)
        moves = self.get_moves(board)
        if not moves:
            elapsed_ms = (time.perf_counter() - start_time) * 1000
            self._write_time_log(move_no, elapsed_ms, None, "pass")
            return None

        book_move = self._book_move(board)
        if book_move in moves:
            elapsed_ms = (time.perf_counter() - start_time) * 1000
            self._write_time_log(move_no, elapsed_ms, book_move, "book")
            return book_move

        best_move = moves[0]
        best_score = float("-inf")
        alpha = float("-inf")
        beta = float("inf")

        moves = self._order_moves_by_weight(moves)
        for move in moves:
            next_board = self._apply_move(board, move, self.color)
            score = -self._negascout(
                next_board,
                depth=self.SEARCH_DEPTH - 1,
                current_color=self._opponent_of(self.color),
                alpha=-beta,
                beta=-alpha,
            )
            if score > best_score:
                best_score = score
                best_move = move
            alpha = max(alpha, best_score)

        elapsed_ms = (time.perf_counter() - start_time) * 1000
        self._write_time_log(move_no, elapsed_ms, best_move, "search")
        return best_move

    def _move_number(self, board: Board) -> int:
        stones = 0
        for row in board:
            for cell in row:
                if cell != Cell.EMPTY:
                    stones += 1
        return stones - 3

    def _log_file_name(self, suffix: str) -> str:
        try:
            player_file = os.environ.get("MYPLAYER_FILE", "")
        except NameError:
            player_file = ""
        stem = player_file.replace("\\", "/").split("/")[-1].removesuffix(".py")
        if not stem:
            stem = "my_book_ab_qweight_search_hash"
        return f"{stem}_{suffix}.txt"

    def _write_time_log(self, move_no: int, elapsed_ms: float, move: Move, source: str):
        with open(self._log_file_name("next_move_profile"), "a", encoding="utf-8") as file:
            file.write(
                f"move_no={move_no} time={elapsed_ms:.1f}ms "
                f"eval_count={self._eval_count} color={self.color} "
                f"hash_get={type(self).SEARCH_HASH_GET_COUNT} "
                f"hash_reg={type(self).SEARCH_HASH_REG_COUNT} "
                f"move={move}\n"
            )

    def _order_moves_by_weight(self, moves: list[Move]) -> list[Move]:
        return sorted(moves, key=lambda move: self.ORDER_WEIGHTS[move[0]][move[1]], reverse=True)

    def _negascout(
        self,
        board: Board,
        depth: int,
        current_color: Cell,
        alpha: float,
        beta: float,
        allow_probcut: bool = True,
    ) -> float:
        # 葉ノードでは、現在手番から見た盤面評価を返す。
        if depth == 0:
            return self._evaluate_for_color(board, current_color)

        original_alpha = alpha
        original_beta = beta
        search_key = self._search_hash_key(board, depth, current_color, allow_probcut)
        cached = self._search_hash_get(search_key, alpha, beta)
        if cached is not None:
            return cached

        # 葉に近い浅い探索では、NegaScoutではなく通常のalpha-betaを使う。
        if depth <= self.SIMPLE_ALPHA_BETA_DEPTH:
            score = self._alpha_beta_simple(board, depth, current_color, alpha, beta)
            self._search_hash_register(search_key, score, original_alpha, original_beta)
            return score

        moves = self._legal_moves(board, current_color)
        next_color = self._opponent_of(current_color)

        # 現在手番だけ合法手がなければパスし、両者なければ終局として評価する。
        if not moves:
            if not self._legal_moves(board, next_color):
                score = self._evaluate_for_color(board, current_color)
            else:
                score = -self._negascout(board, depth, next_color, -beta, -alpha, allow_probcut)
            self._search_hash_register(search_key, score, original_alpha, original_beta)
            return score

        # 深く読む前に、浅い評価で枝刈りできるか試す。
        if allow_probcut and depth >= self.PROBCUT_MIN_DEPTH:
            cut_score = self._probcut(board, depth, current_color, alpha, beta)
            if cut_score is not None:
                self._search_hash_register(search_key, cut_score, original_alpha, original_beta)
                return cut_score

        # 良さそうな手から読むことで、alpha-betaの枝刈りを起こしやすくする。
        moves = self._order_moves_by_weight(moves)
        if depth >= 2 and len(moves) > 1:
            moves.sort(
                key=lambda move: self._evaluate_for_color(
                    self._apply_move(board, move, current_color), current_color
                ),
                reverse=True,
            )

        search_window = beta
        best_score = float("-inf")

        for index, move in enumerate(moves):
            next_board = self._apply_move(board, move, current_color)
            # 1手目は通常窓、2手目以降は狭い窓で先に読む。
            score = -self._negascout(
                next_board, depth - 1, next_color, -search_window, -alpha, allow_probcut
            )

            # 狭い窓で有望そうなら、通常窓で読み直す。
            if alpha < score < beta and index > 0 and depth > 1:
                score = -self._negascout(
                    next_board, depth - 1, next_color, -beta, -score, allow_probcut
                )

            best_score = max(best_score, score)
            alpha = max(alpha, score)
            if alpha >= beta:
                break
            search_window = alpha + 1

        self._search_hash_register(search_key, best_score, original_alpha, original_beta)
        return best_score

    def _search_hash_key(
        self,
        board: Board,
        depth: int,
        current_color: Cell,
        allow_probcut: bool,
    ) -> tuple[tuple[int, ...], int, int, bool]:
        color_key = 1 if current_color == Cell.BLACK else 2
        return (self._board_key(board), color_key, depth, allow_probcut)

    @classmethod
    def _search_hash_index(cls, key: tuple[tuple[int, ...], int, int, bool]) -> int:
        board_key, color, depth, allow_probcut = key
        value = color * 131 + depth * 17 + int(allow_probcut)
        for cell in board_key:
            value = (value * 17 + cell + 1) & 0xFFFFFFFFFFFFFFFF
        return value & cls.SEARCH_HASH_MASK

    @classmethod
    def _search_hash_get(
        cls,
        key: tuple[tuple[int, ...], int, int, bool],
        alpha: float,
        beta: float,
    ) -> float | None:
        entry = cls.SEARCH_HASH_TABLE[cls._search_hash_index(key)]
        if entry is None:
            return None
        entry_key, lower, upper = entry
        if entry_key != key:
            return None
        if lower >= beta:
            cls.SEARCH_HASH_GET_COUNT += 1
            return lower
        if upper <= alpha:
            cls.SEARCH_HASH_GET_COUNT += 1
            return upper
        if lower == upper:
            cls.SEARCH_HASH_GET_COUNT += 1
            return lower
        return None

    @classmethod
    def _search_hash_register(
        cls,
        key: tuple[tuple[int, ...], int, int, bool],
        score: float,
        alpha: float,
        beta: float,
    ) -> None:
        lower = float("-inf")
        upper = float("inf")
        if score <= alpha:
            upper = score
        elif score >= beta:
            lower = score
        else:
            lower = score
            upper = score
        cls.SEARCH_HASH_REG_COUNT += 1
        cls.SEARCH_HASH_TABLE[cls._search_hash_index(key)] = (key, lower, upper)

    def _alpha_beta_simple(
        self,
        board: Board,
        depth: int,
        current_color: Cell,
        alpha: float,
        beta: float,
    ) -> float:
        if depth == 0:
            return self._evaluate_for_color(board, current_color)

        moves = self._legal_moves(board, current_color)
        next_color = self._opponent_of(current_color)

        if not moves:
            if not self._legal_moves(board, next_color):
                return self._evaluate_for_color(board, current_color)
            return -self._alpha_beta_simple(board, depth, next_color, -beta, -alpha)

        best_score = float("-inf")
        for move in moves:
            next_board = self._apply_move(board, move, current_color)
            score = -self._alpha_beta_simple(next_board, depth - 1, next_color, -beta, -alpha)
            best_score = max(best_score, score)
            alpha = max(alpha, score)
            if alpha >= beta:
                break

        return best_score

    def _probcut(self, board: Board, depth: int, current_color: Cell, alpha: float, beta: float):
        margin = self.PROBCUT_MARGIN + 0.02 * depth
        estimate = self._evaluate_for_color(board, current_color)
        if estimate >= beta + margin:
            return beta
        if estimate <= alpha - margin:
            return alpha
        if depth < self.PROBCUT_MIN_DEPTH:
            return None

        if depth < len(self.PROBCUT_SHALLOW_DEPTHS):
            probe_depth = self.PROBCUT_SHALLOW_DEPTHS[depth]
        else:
            probe_depth = max(1, depth - 8)
        if probe_depth <= 0:
            return None
        if estimate + margin >= beta:
            high = beta + margin
            high_score = self._negascout(
                board, probe_depth, current_color, high - 0.001, high, allow_probcut=False
            )
            if high_score >= high:
                return beta

        if estimate - margin <= alpha:
            low = alpha - margin
            low_score = self._negascout(
                board, probe_depth, current_color, low, low + 0.001, allow_probcut=False
            )
            if low_score <= low:
                return alpha

        return None

    def _evaluate_for_color(self, board: Board, color: Cell) -> float:
        score = self._evaluate_black_perspective(board)
        if color == Cell.BLACK:
            return score
        return -score

    def _evaluate_black_perspective(self, board: Board) -> float:
        self._eval_count += 1
        flat_board = self._flatten_board(board)
        group_outputs = []
        for name, patterns in self.PATTERN_INDEXES.items():
            group_sum = 0.0
            for pattern in patterns:
                key = self._pattern_key(flat_board, pattern)
                group_sum += self._pattern_value(name, key)
            group_outputs.append(group_sum)

        add_value = self._add_value(self._additional_key(board))
        values = group_outputs + [add_value]
        final_dense, final_bias = self._params()[2]
        score = final_bias
        for i in range(4):
            score += values[i] * final_dense[i] // self.WEIGHT_SCALE
        return score / self.WEIGHT_SCALE

    @classmethod
    def _params(cls):
        if cls.PARAMS is not None:
            return cls.PARAMS

        weights = tuple(int(round(value * cls.WEIGHT_SCALE)) for value in cls.WEIGHTS)
        pos = 0

        def take():
            nonlocal pos
            value = weights[pos]
            pos += 1
            return value

        patterns = {}
        for name, size in (("diagonal8", 8), ("edge2X", 10), ("triangle", 10)):
            dense0 = tuple(tuple(take() for _ in range(size * 2)) for _ in range(16))
            bias0 = tuple(take() for _ in range(16))
            dense1 = tuple(tuple(take() for _ in range(16)) for _ in range(16))
            bias1 = tuple(take() for _ in range(16))
            dense2 = tuple(take() for _ in range(16))
            bias2 = take()
            patterns[name] = (size, dense0, bias0, dense1, bias1, dense2, bias2)

        add_dense0 = tuple(tuple(take() for _ in range(3)) for _ in range(8))
        add_bias0 = tuple(take() for _ in range(8))
        add_dense1 = tuple(take() for _ in range(8))
        add_bias1 = take()
        final_dense = tuple(take() for _ in range(4))
        final_bias = take()
        cls.PARAMS = (patterns, (add_dense0, add_bias0, add_dense1, add_bias1), (final_dense, final_bias))
        return cls.PARAMS

    @classmethod
    def _pattern_value(cls, name: str, key: int) -> int:
        cache_key = (name, key)
        cached = cls.PATTERN_CACHE.get(cache_key)
        if cached is not None:
            return cached

        size, dense0, bias0, dense1, bias1, dense2, bias2 = cls._params()[0][name]
        active_indexes = []
        n = key
        for i in range(size - 1, -1, -1):
            digit = n % 3
            n //= 3
            if digit == 0:
                active_indexes.append(i)
            elif digit == 1:
                active_indexes.append(size + i)

        hidden0 = []
        for out_i in range(16):
            value = bias0[out_i]
            row = dense0[out_i]
            for in_i in active_indexes:
                value += row[in_i]
            hidden0.append(cls._q_leaky_relu(value))

        result = bias2
        for out_i in range(16):
            value = bias1[out_i]
            row = dense1[out_i]
            for in_i in range(16):
                value += hidden0[in_i] * row[in_i] // cls.WEIGHT_SCALE
            result += cls._q_leaky_relu(value) * dense2[out_i] // cls.WEIGHT_SCALE

        result = cls._q_leaky_relu(result)
        cls.PATTERN_CACHE[cache_key] = result
        return result

    @classmethod
    def _add_value(cls, key: int) -> int:
        cached = cls.ADD_CACHE.get(key)
        if cached is not None:
            return cached

        tmp = key
        sur1 = tmp % 51
        tmp //= 51
        sur0 = tmp % 51
        mobility = tmp // 51 - 30
        arr = (
            mobility * cls.WEIGHT_SCALE // 30,
            (sur0 - 15) * cls.WEIGHT_SCALE // 15,
            (sur1 - 15) * cls.WEIGHT_SCALE // 15,
        )
        dense0, bias0, dense1, bias1 = cls._params()[1]

        hidden = []
        for out_i in range(8):
            value = bias0[out_i]
            row = dense0[out_i]
            for in_i in range(3):
                value += arr[in_i] * row[in_i] // cls.WEIGHT_SCALE
            hidden.append(cls._q_leaky_relu(value))

        result = bias1
        for i in range(8):
            result += hidden[i] * dense1[i] // cls.WEIGHT_SCALE
        result = cls._q_leaky_relu(result)
        cls.ADD_CACHE[key] = result
        return result

    @staticmethod
    def _q_leaky_relu(value: int) -> int:
        if value >= 0:
            return value
        return -((-value) // 100)

    @staticmethod
    def _leaky_relu(value: float) -> float:
        if value >= 0.0:
            return value
        return 0.01 * value

    def _pattern_key(self, flat_board: list[Cell], pattern: tuple[int, ...]) -> int:
        key = 0
        for index in pattern:
            cell = flat_board[index]
            if cell == Cell.BLACK:
                digit = 0
            elif cell == Cell.WHITE:
                digit = 1
            else:
                digit = 2
            key = key * 3 + digit
        return key

    def _additional_key(self, board: Board) -> int:
        mobility = len(self._legal_moves(board, Cell.BLACK)) - len(self._legal_moves(board, Cell.WHITE))
        mobility = max(-30, min(30, mobility))
        surround_black, surround_white = self._surround_counts(board)
        surround_black = max(0, min(50, surround_black))
        surround_white = max(0, min(50, surround_white))
        return ((mobility + 30) * 51 + surround_black) * 51 + surround_white

    def _surround_counts(self, board: Board) -> tuple[int, int]:
        counts = [0, 0]
        for row in self.BOARD_INDEXES:
            for col in self.BOARD_INDEXES:
                cell = board[row][col]
                if cell == Cell.EMPTY:
                    continue
                index = 0 if cell == Cell.BLACK else 1
                for delta_row, delta_col in self.DIRECTIONS:
                    r = row + delta_row
                    c = col + delta_col
                    if 0 <= r < 8 and 0 <= c < 8 and board[r][c] == Cell.EMPTY:
                        counts[index] += 1
        return counts[0], counts[1]

    def _flatten_board(self, board: Board) -> list[Cell]:
        return [cell for row in board for cell in row]

    def _legal_moves(self, board: Board, color: Cell) -> list[Move]:
        if color == self.color:
            return self.get_moves(board)

        moves = []
        for row in self.BOARD_INDEXES:
            for col in self.BOARD_INDEXES:
                if board[row][col] == Cell.EMPTY and self._flips_for_color(board, row, col, color):
                    moves.append((row, col))
        return moves

    def _apply_move(self, board: Board, move: Move, color: Cell) -> Board:
        row, col = move
        next_board = [board_row[:] for board_row in board]
        next_board[row][col] = color

        if color == self.color:
            flips = self.get_flips(board, row, col)
        else:
            flips = self._flips_for_color(board, row, col, color)
        for flip_row, flip_col in flips:
            next_board[flip_row][flip_col] = color

        return next_board

    def _flips_for_color(self, board: Board, row: int, col: int, color: Cell) -> list[Move]:
        if color == self.color:
            return self.get_flips(board, row, col)
        if board[row][col] != Cell.EMPTY:
            return []

        opponent_color = self._opponent_of(color)
        flips = []

        for delta_row, delta_col in self.DIRECTIONS:
            direction_flips = []
            current_row = row + delta_row
            current_col = col + delta_col

            while (
                0 <= current_row < 8
                and 0 <= current_col < 8
                and board[current_row][current_col] == opponent_color
            ):
                direction_flips.append((current_row, current_col))
                current_row += delta_row
                current_col += delta_col

            if (
                direction_flips
                and 0 <= current_row < 8
                and 0 <= current_col < 8
                and board[current_row][current_col] == color
            ):
                flips.extend(direction_flips)

        return flips

    @classmethod
    def _book_cache(cls):
        if cls.BOOK_CACHE is not None:
            return cls.BOOK_CACHE

        cache = {}
        for line in cls.BOOK_LINES:
            prefix = line[:-2]
            move_text = line[-2:]
            for transform in range(4):
                board = cls._initial_board()
                current_color = Cell.BLACK
                for i in range(0, len(prefix), 2):
                    move = cls._coord_to_move(prefix[i:i + 2], transform)
                    board = cls._apply_move_for_color(board, move, current_color)
                    current_color = Cell.WHITE if current_color == Cell.BLACK else Cell.BLACK
                cache[(cls._board_key(board), current_color)] = cls._coord_to_move(move_text, transform)

        cls.BOOK_CACHE = cache
        return cache

    def _book_move(self, board: Board) -> Move:
        return self._book_cache().get((self._board_key(board), self.color))

    @staticmethod
    def _initial_board() -> Board:
        board = [[Cell.EMPTY for _ in range(8)] for _ in range(8)]
        board[3][3] = Cell.WHITE
        board[3][4] = Cell.BLACK
        board[4][3] = Cell.BLACK
        board[4][4] = Cell.WHITE
        return board

    @staticmethod
    def _coord_to_move(coord: str, transform: int) -> Move:
        col = ord(coord[0]) - ord("a")
        row = int(coord[1]) - 1
        if transform == 0:
            return (row, col)
        if transform == 1:
            return (col, row)
        if transform == 2:
            return (7 - row, 7 - col)
        return (7 - col, 7 - row)

    @classmethod
    def _apply_move_for_color(cls, board: Board, move: Move, color: Cell) -> Board:
        row, col = move
        next_board = [board_row[:] for board_row in board]
        next_board[row][col] = color
        opponent_color = Cell.WHITE if color == Cell.BLACK else Cell.BLACK

        for delta_row, delta_col in cls.DIRECTIONS:
            direction_flips = []
            current_row = row + delta_row
            current_col = col + delta_col
            while (
                0 <= current_row < 8
                and 0 <= current_col < 8
                and board[current_row][current_col] == opponent_color
            ):
                direction_flips.append((current_row, current_col))
                current_row += delta_row
                current_col += delta_col

            if (
                direction_flips
                and 0 <= current_row < 8
                and 0 <= current_col < 8
                and board[current_row][current_col] == color
            ):
                for flip_row, flip_col in direction_flips:
                    next_board[flip_row][flip_col] = color

        return next_board

    @staticmethod
    def _board_key(board: Board) -> tuple[int, ...]:
        values = []
        for row in board:
            for cell in row:
                if cell == Cell.BLACK:
                    values.append(1)
                elif cell == Cell.WHITE:
                    values.append(2)
                else:
                    values.append(0)
        return tuple(values)

    def _opponent_of(self, color: Cell) -> Cell:
        if color == self.color:
            return self.opponent_color
        if color == self.opponent_color:
            return self.color
        return Cell.WHITE if color == Cell.BLACK else Cell.BLACK
